<?php $l=$this->getVar('liveclassLabels');$s=$this->getVar('liveclassSession');$e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$icons=$this->getObject('iconservice','ui');$manage=$this->getVar('liveclassMayManage',false);$state=$this->getVar('liveclassLifecycle',array('phase'=>'upcoming','can_join'=>false));$clock=$this->getObject('timeanddateservice','timeanddate-service');$image=filter_var($s['image_url']??'',FILTER_VALIDATE_URL)?$s['image_url']:''; ?>
<section class="liveclass-page liveclass-event-page"><div class="liveclass-event-hero"><?php if($image!==''): ?><img src="<?php echo $e($image); ?>" alt=""><?php else: ?><div class="liveclass-event-art" aria-hidden="true"><?php echo $icons->render('video',array('decorative'=>true)); ?></div><?php endif; ?><time><?php echo $e($clock->formatDateTime($s['starts_at'])); ?></time></div><header><p class="chisimba-eyebrow"><?php echo $e($l[$s['session_type']==='webinar'?'webinar_type':'context_type']); ?></p><h1><?php echo $e($s['name']); ?></h1><p><?php echo nl2br($e($s['description'])); ?></p></header><?php if($this->getVar('liveclassMessage','')!==''): ?><p class="chisimba-notice chisimba-notice-success"><?php echo $e($this->getVar('liveclassMessage')); ?></p><?php endif; ?><?php if($this->getVar('liveclassError','')!==''): ?><p class="chisimba-notice chisimba-notice-error"><?php echo $e($this->getVar('liveclassError')); ?></p><?php endif; ?><dl class="liveclass-details"><dt><?php echo $e($l['starts']); ?></dt><dd><?php echo $e($clock->formatDateTime($s['starts_at'])); ?></dd><dt><?php echo $e($l['duration']); ?></dt><dd><?php echo (int)$s['duration_minutes']; ?></dd></dl><div class="chisimba-form-actions"><?php if(!empty($state['can_join'])): ?><a class="button chisimba-button-primary" href="<?php echo $e($this->uri(array('action'=>'join','id'=>$s['id']))); ?>"><?php echo $icons->render($manage?'play':'log-in',array('decorative'=>true)); ?><span><?php echo $e($l[$manage?'start':'join']); ?></span></a><?php elseif(($state['phase']??'')==='upcoming'): ?><span class="button chisimba-button-primary liveclass-join-disabled" aria-disabled="true"><?php echo $icons->render('lock',array('decorative'=>true)); ?><span><?php echo $e($l['join']); ?></span></span><span><?php echo $e(strtr($l['join_locked'],array('{minutes}'=>$this->getVar('liveclassJoinWindow',15)))); ?></span><?php endif; ?><?php if($manage&&$s['status']==='scheduled'): ?><form method="post" action="<?php echo $e($this->uri(array('action'=>'end','id'=>$s['id']))); ?>"><input type="hidden" name="csrf_token" value="<?php echo $e($this->getVar('liveclassCsrf')); ?>"><button class="button chisimba-button-secondary" type="submit"><?php echo $icons->render('square',array('decorative'=>true)); ?><span><?php echo $e($l['end']); ?></span></button></form><form method="post" action="<?php echo $e($this->uri(array('action'=>'cancel','id'=>$s['id']))); ?>"><input type="hidden" name="csrf_token" value="<?php echo $e($this->getVar('liveclassCsrf')); ?>"><button class="button chisimba-button-danger" type="submit"><?php echo $icons->render('x',array('decorative'=>true)); ?><span><?php echo $e($l['cancel_session']); ?></span></button></form><?php endif; ?></div><?php $jobs=$this->getVar('liveclassReminderJobs',array());if($manage&&$jobs): ?><section><h2><?php echo $e($l['reminders']); ?></h2><div class="liveclass-grid"><?php foreach($jobs as $job): ?><article class="liveclass-card"><strong><?php echo $e($l[(int)$job['lead_minutes']===1440?'reminder_24h':'reminder_1h']); ?></strong><span><?php echo $e($l['reminder_'.$job['status']]??$job['status']); ?></span><?php if($job['status']==='queued'): ?><small><?php echo $e($l['reminder_recipients']); ?>: <?php echo (int)$job['recipient_count']; ?></small><?php endif; ?></article><?php endforeach; ?></div></section><?php endif; ?><section><h2><?php echo $e($l['recordings']); ?></h2><?php $recordings=$this->getVar('liveclassRecordings',array());if(!$recordings): ?><p><?php echo $e($l['no_recordings']); ?></p><?php else: ?><div class="liveclass-grid"><?php foreach($recordings as $recording): ?><article class="liveclass-card"><h3><?php echo $e($recording['name']); ?></h3><?php foreach($recording['formats'] as $format): ?><a class="button chisimba-button-secondary" href="<?php echo $e($format['url']); ?>" rel="noopener"><?php echo $icons->render('play',array('decorative'=>true)); ?><span><?php echo $e($format['type']); ?></span></a><?php endforeach; ?></article><?php endforeach; ?></div><?php endif; ?></section></section>
